.ev-time{
  flex:0 0 42px;font-family:var(--mono);font-size:12px;color:var(--mut);
  padding-top:3px;
}
.ev-main{min-width:0;flex:1}
.ev-top{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.comp{font-size:11.5px;color:var(--mut)}
.eid{margin-left:auto;font-family:var(--mono);font-size:10.5px;color:var(--mut2)}
.ev-title{font-size:13.5px;margin-top:2px}
.badge{
  font-size:10.5px;padding:1px 8px;border-radius:5px;white-space:nowrap;
  color:var(--c,#8fa3b8);
  background:color-mix(in srgb,var(--c,#8fa3b8) 15%,transparent);
  border:1px solid color-mix(in srgb,var(--c,#8fa3b8) 45%,transparent);
}
.sev{font-size:10px;padding:0 6px;border-radius:4px;white-space:nowrap;font-weight:600}
.sev.w{color:var(--amber);border:1px solid #e3b34155;background:#e3b3411a}
.sev.h{color:var(--red);border:1px solid #f8514955;background:#f851491a}
.ctag{font-size:10px;padding:0 6px;border-radius:4px;white-space:nowrap}
.ctag.up{color:var(--green);border:1px solid #3fb95044;background:#12261c}
.ctag.down{color:#79b8ff;border:1px solid #4c8dff44;background:#12203a}
.ctag.dim{color:var(--mut2);border:1px dashed var(--line2)}

/* ============ 右侧面板 ============ */
.pane{
  background:var(--panel);border:1px solid var(--line);border-radius:12px;
  padding:12px 14px;flex:0 0 auto;
}
.d-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.d-comp{font-size:12px;color:var(--mut)}
.d-time{font-family:var(--mono);font-size:12px;color:var(--mut)}
.d-head .eid{margin-left:auto}
.d-title{font-size:15px;margin:8px 0 4px;line-height:1.45}
.d-meta{font-size:11.5px;color:var(--mut2);margin-bottom:8px}
.d-rows{width:100%;border-collapse:collapse;font-size:12.5px;margin:6px 0}
.d-rows th{
  text-align:left;color:var(--mut2);font-weight:400;font-size:10.5px;
  padding:2px 8px;border-bottom:1px solid var(--line);letter-spacing:1px;
}
.d-rows td{padding:4px 8px;border-bottom:1px dashed #1c2938;vertical-align:top}
.d-rows td:first-child{color:var(--mut);white-space:nowrap}
.d-rows .b{font-family:var(--mono);color:var(--mut);font-size:12px}
.d-rows .a{font-family:var(--mono);color:#7ee2a8;font-size:12px}
.d-notes{margin:6px 0;padding-left:18px;font-size:12px;color:#9db0c5}
.d-notes li{margin:3px 0}
.d-causal{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:10px 0 4px}
.dc h3{
  margin:0 0 6px;font-size:11px;color:var(--mut2);font-weight:600;letter-spacing:1px;
}
.dc{display:flex;flex-direction:column;align-items:flex-start;gap:5px}
.link-chip{
  display:inline-flex;align-items:center;gap:6px;max-width:100%;text-align:left;
  padding:3px 9px;border-radius:7px;border:1px solid var(--line);
  background:var(--panel2);color:var(--mut);font-size:11.5px;cursor:pointer;
  font-family:var(--mono);
}
.link-chip:hover{border-color:var(--line2);color:var(--txt)}
.none{font-size:11.5px;color:var(--mut2)}
.locbtn{
  margin-top:8px;width:100%;padding:7px 0;border-radius:8px;cursor:pointer;
  background:#182842;border:1px solid #2c4a7c;color:#9cc3ff;font-size:12.5px;
}
.locbtn:hover{background:#1d3355}

/* ============ 回放 ============ */
.replay-ctl{display:flex;flex-direction:column;gap:6px;margin-bottom:8px}
input[type=range]{width:100%;accent-color:var(--acc);cursor:pointer}
.replay-meta{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.replay-meta b{font-family:var(--mono);font-size:12.5px;color:#bcd2ec;font-weight:600}
.nextbtn{
  text-align:left;padding:6px 10px;border-radius:8px;cursor:pointer;
  background:var(--panel2);border:1px dashed var(--line2);
  color:var(--mut);font-size:11.5px;
}
.nextbtn:hover{color:var(--txt);border-color:var(--acc)}
.sg{margin-bottom:10px}
.sg-h{
  display:flex;align-items:center;gap:7px;font-size:12px;color:#a9bdd6;
  font-weight:600;padding:4px 6px;border-bottom:1px solid var(--line);
  margin-bottom:3px;
}
.sg-t{margin-left:auto;font-size:10px;color:var(--mut2);font-weight:400;letter-spacing:1px}
.sr{display:flex;align-items:baseline;gap:8px;font-size:12.5px;padding:3px 6px;border-radius:6px}
.sr .k{color:var(--mut);flex:0 0 118px}
.sr .v{font-family:var(--mono);color:var(--txt);font-size:12.5px}
.sr .by{margin-left:auto;font-family:var(--mono);font-size:10.5px;color:var(--mut2)}
.sr.fresh{background:#12261c;outline:1px solid #1f3a2b}
.sr.fresh .by{color:var(--green)}

/* ============ 页脚 ============ */
.foot{
  flex:0 0 auto;padding:6px 18px;font-size:11px;color:var(--mut2);
  border-top:1px solid var(--line);background:var(--bg2);
}

@media (max-width:980px){
  body{height:auto;overflow:auto}
  .layout{grid-template-columns:1fr}
  .col-left,.col-right{overflow:visible}
  .timeline{min-height:300px}
}

